/* crosswalk cards, r28. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28a"]=[{"q": "f(x, y) = (x² + y)/(1 + x²y²). Which technique shows it is continuous everywhere?", "a": "the each-place technique", "w": ["the one-knob technique", "the knobs-miss-jumps technique", "the slope-grid technique"], "why": "It is built from the places x and y by sums, products and a quotient whose bottom is never 0."}, {"q": "For f(x, y), the slope at a of x ↦ f(x, b). What is it called on the page?", "a": "the partial slope along x", "w": ["the slope along y", "the best flat map", "the uphill vector"], "why": "Hold y at b, turn the x knob, and take rung 13’s slope."}, {"q": "f(x, y) = x²y + y³. What is f<sub>x</sub>?", "a": "2xy", "w": ["2xy + x²", "x² + 3y²", "2x + 3y²"], "why": "y is held still, so it acts like a number."}, {"q": "f(x, y) = x²y + y³. What is f<sub>y</sub>?", "a": "x² + 3y²", "w": ["2xy", "3y²", "2xy + 3y²"], "why": "x is held still; x² is a constant times y."}, {"q": "Accepted name for a partial slope?", "a": "a partial derivative", "w": ["a directional derivative", "a total derivative", "a gradient"], "why": "Written ∂f/∂x or f<sub>x</sub>."}, {"q": "f = xy/(x² + y²), f(0, 0) = 0. Is f continuous at (0, 0)?", "a": "no: f(t, t) = ½ for every t ≠ 0", "w": ["yes: both partial slopes are 0", "yes: f is 0 on both axes", "no: f has no partial slopes there"], "why": "The knobs-miss-jumps technique: the jump hides off the axes."}, {"q": "A function has both partial slopes at a point. What follows about continuity there?", "a": "nothing: it can still jump", "w": ["it is continuous there", "it has a best flat map there", "it is continuous along every curve"], "why": "28a3’s example has both partials and a jump."}, {"q": "g = x²y/(x⁴ + y²) heads to 0 along every straight line through (0, 0). Does it head to 0?", "a": "no: along y = x² it stays at ½", "w": ["yes: every line agrees", "yes: both partials are 0", "no: it blows up on the axes"], "why": "A curved road can still find a step."}, {"q": "A line reads ∂(x²y)/∂x = 2xy + x². What goes wrong?", "a": "y is held still, so its slope along x is 0", "w": ["the power technique gives x, not 2x", "the order of the knobs was swapped", "x² should be x²y"], "why": "Only x moves; the product technique sees y as a number."}, {"q": "|xᵢ − wᵢ| ≤ |x − w|. Why is it true?", "a": "|x − w|² is a sum of squares, one of them (xᵢ − wᵢ)²", "w": ["the triangle technique", "each place is at most 1", "the dot-bound technique"], "why": "Dropping the other squares can only make the sum smaller."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28b"]=[{"q": "f(w + h) = f(w) + L(h) + r(h) with L straight and |r(h)|/|h| → 0. What is L?", "a": "the best flat map of f at w", "w": ["the slope grid of f", "the leftover", "the partial slope along h"], "why": "Accepted name: the derivative Df(w)."}, {"q": "How many best flat maps can a function have at one point?", "a": "at most one", "w": ["exactly one, always", "one for each direction", "two, one per knob"], "why": "The one-flat-map technique: (L − M)(u) heads to 0 and is fixed, so it is 0."}, {"q": "f has a best flat map L at w. What is column j of the grid of L?", "a": "the partial slope ∂f/∂xⱼ (w)", "w": ["the slope along the vector (1, 1)", "the value f(eⱼ)", "the j-th place of f(w)"], "why": "The slope-grid technique: step along knob j only."}, {"q": "Accepted name for the slope grid?", "a": "the Jacobian matrix", "w": ["the Hessian matrix", "the identity grid", "the gradient"], "why": "Its entries are ∂fᵢ/∂xⱼ."}, {"q": "Every partial slope of f exists near a and is continuous at w. What follows?", "a": "f has a best flat map at w", "w": ["f is a straight map", "the partials are 0 at w", "f is one-to-one near w"], "why": "The smooth-knobs technique: walk one knob per leg and use 14c on each."}, {"q": "f has a best flat map at w. Must f be continuous at w?", "a": "yes", "w": ["no: only along the axes", "no: only if the partials are continuous", "only for one input"], "why": "The flat-means-continuous technique: L(h) and r(h) both head to 0."}, {"q": "f = x² sin(1/x) + y² (with f(0, y) = y²) has Df(0, 0) = 0. Is f<sub>x</sub> continuous at (0, 0)?", "a": "no", "w": ["yes", "only along y = 0", "only if f<sub>y</sub> is"], "why": "Smooth knobs give the flat map, not the other way round."}, {"q": "A leftover has |r(h)|/|h| ≤ 1 for small h. Is L then the best flat map?", "a": "not unless the ratio heads to 0", "w": ["yes, a bounded leftover is enough", "yes, if L is straight", "only for one input"], "why": "|x| with L = 0 has a bounded ratio and no flat map."}, {"q": "f = x² + 3y at (2, −1), u = (3/5, 4/5). What is the slope of f along u?", "a": "4.8", "w": ["7", "9.6", "5"], "why": "L(u) = 4·0.6 + 3·0.8, and u has length 1."}, {"q": "Polar map T(r, θ) = (r cos θ, r sin θ). What is the slope grid’s column along θ?", "a": "(−r sin θ, r cos θ)", "w": ["(cos θ, sin θ)", "(−sin θ, cos θ)", "(r cos θ, r sin θ)"], "why": "Hold r, turn θ: the point moves round a circle of radius r."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28c"]=[{"q": "|Ah| ≤ c|h|, with c² the sum of the squares of A’s entries. What is this?", "a": "the stretch-bound technique", "w": ["the dot-bound technique", "the area-scale technique", "the segment-bound technique"], "why": "Each row obeys the dot-bound; squaring and adding gives c."}, {"q": "A has rows (3, 4) and (0, 5). What is the stretch-bound c?", "a": "√50", "w": ["12", "5", "√41"], "why": "9 + 16 + 0 + 25 = 50."}, {"q": "g has best flat map B at w, f has best flat map A at g(w). What is the slope grid of f ∘ g at w?", "a": "AB", "w": ["BA", "A + B", "A at a times B"], "why": "The chain-of-flat-maps technique: g is done first, so its grid is on the right."}, {"q": "A line reads D(f ∘ g)(w) = Df(w) Dg(w). What goes wrong?", "a": "f’s flat map must be taken at g(w)", "w": ["the order should be Dg Df", "the grids should be added", "nothing, it is the chain technique"], "why": "f acts on the point g(w), not on w."}, {"q": "Slope of f(x(t), y(t)) by the roads-add technique?", "a": "f<sub>x</sub> x′(t) + f<sub>y</sub> y′(t)", "w": ["f<sub>x</sub> + f<sub>y</sub>", "f<sub>x</sub> y′(t) + f<sub>y</sub> x′(t)", "x′(t) + y′(t)"], "why": "One term per road: how much f cares, times how fast that input moves."}, {"q": "f = xy along (cos t, sin t). What is the slope at t = π/4?", "a": "0", "w": ["√2", "1", "½"], "why": "cos²t − sin²t = 0 there."}, {"q": "Entry (i, j) of the product AB, read as roads. What is it?", "a": "a sum over the middle quantities, one road each", "w": ["the largest single road", "the product of all the roads", "the road through the first middle quantity"], "why": "Slope along one road times slope along the next, added over the middle."}, {"q": "Accepted name for the chain-of-flat-maps technique?", "a": "the multivariable chain rule", "w": ["the product rule", "the inverse function rule", "the mean value rule"], "why": "With one input and one output it is 13e’s chain technique."}, {"q": "f = xy/(x² + y²) along (t, t). Do the roads add at t = 0?", "a": "no: f has no best flat map at (0, 0)", "w": ["yes, both give 0", "yes, the partials exist", "no: the path has no slope"], "why": "The roads-add technique needs f’s best flat map, not just its partials."}, {"q": "g(t) = (t, t², t³), f = xy + z. How many roads feed the slope of f(g(t))?", "a": "three", "w": ["one", "two", "six"], "why": "One for each middle quantity x, y, z."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28d"]=[{"q": "f<sub>xy</sub> on this page. Which knob is turned first?", "a": "x first, then y", "w": ["y first, then x", "both at once", "whichever is easier"], "why": "f<sub>xy</sub> is the slope along y of f<sub>x</sub>."}, {"q": "f(a + h, b + k) − f(a + h, b) − f(a, b + k) + f(a, b). What is it called?", "a": "the corner sum", "w": ["the leftover", "the column sum", "the mixed slope"], "why": "One number read two ways in the swap-knobs proof."}, {"q": "f<sub>xy</sub> and f<sub>yx</sub> exist near (a, b) and are continuous at it. What follows?", "a": "f<sub>xy</sub>(a, b) = f<sub>yx</sub>(a, b)", "w": ["f<sub>xx</sub> = f<sub>yy</sub>", "f has no top there", "the corner sum is 0"], "why": "The swap-knobs technique."}, {"q": "f = xy(x² − y²)/(x² + y²), f(0, 0) = 0. What are f<sub>xy</sub>(0, 0) and f<sub>yx</sub>(0, 0)?", "a": "−1 and 1", "w": ["0 and 0", "1 and 1", "−1 and −1"], "why": "The order-matters technique: the mixed slopes are not continuous there."}, {"q": "Which technique licenses Δ = u′(a + sh)h for u(x) = f(x, b + k) − f(x, b)?", "a": "the average-slope technique", "w": ["the swap-knobs technique", "the one-knob technique", "the each-place technique"], "why": "14c on u, with 0 < s < 1."}, {"q": "A line reads Δ = f<sub>xy</sub>(a, b) hk exactly. What goes wrong?", "a": "the average-slope technique gives an in-between point", "w": ["the order of the knobs is wrong", "Δ is always 0", "hk should be h + k"], "why": "For x²y² on [1, 2]² the point is (1.5, 1.5), not (1, 1)."}, {"q": "f = x³y. Is f<sub>xx</sub>(1, 2) equal to (f<sub>x</sub>(1, 2))²?", "a": "no: 12 against 36", "w": ["yes: both are 36", "yes: both are 12", "no: f<sub>xx</sub> does not exist"], "why": "f<sub>xx</sub> is the slope of f<sub>x</sub>, not its square."}, {"q": "f = eˣ cos y + x²y³. Do f<sub>xy</sub> and f<sub>yx</sub> agree?", "a": "yes, both are −eˣ sin y + 6xy²", "w": ["no, they differ by 6xy²", "only at (0, 0)", "only where cos y = 0"], "why": "The second slopes are continuous, so the order cannot matter."}, {"q": "Accepted name for the swap-knobs technique?", "a": "symmetry of second derivatives", "w": ["the chain rule", "the implicit function rule", "the mean value rule"], "why": "Mixed partial derivatives agree when they are continuous."}, {"q": "f<sub>x</sub> = y and f<sub>y</sub> = 2x. Is there a smoothly sloped f with smooth second slopes?", "a": "no: the mixed slopes would be 1 and 2", "w": ["yes: f = xy", "yes: f = 2xy", "yes: f = x² + y²"], "why": "Swap-knobs would force 1 = 2."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28e"]=[{"q": "|φ(x) − φ(x′)| ≤ nε|x − x′| when every slope entry is at most ε. What is this?", "a": "the segment-bound technique", "w": ["the stretch-bound technique", "the shrinking-map technique", "the local-undo technique"], "why": "Walk the segment and use 14c on each output."}, {"q": "φ<sub>y</sub>(x) = x + A⁻¹(y − f(x)). When is x still under it?", "a": "exactly when f(x) = y", "w": ["exactly when A = I", "when x = y", "when f(x) = 0"], "why": "The correction is 0 exactly at an answer."}, {"q": "det Df(w) ≠ 0 and f is smoothly sloped. What follows?", "a": "f can be undone on a patch around w", "w": ["f is one-to-one everywhere", "f is straight near w", "f has a top at w"], "why": "The local-undo technique, by 24c’s shrinking map."}, {"q": "Which technique licenses “exactly one x in the ball with f(x) = y”?", "a": "the shrinking-map technique", "w": ["the segment-bound technique", "the nonzero-det technique", "the each-place technique"], "why": "φ<sub>y</sub> shrinks gaps by half and keeps the ball, so 24c applies."}, {"q": "g undoes f near w. What is Dg(y)?", "a": "Df(g(y))⁻¹", "w": ["Df(y)⁻¹", "Df(g(y))", "Df(w)⁻¹ for every y"], "why": "The undo-slope technique: f’s grid is taken at g(y)."}, {"q": "Polar map at r = 1, θ = 0 and at r = 1, θ = 2π. What does this show?", "a": "an undoable grid does not make the map one-to-one everywhere", "w": ["the det is 0 there", "the polar map has no slope grid", "the local-undo technique is false"], "why": "Both points land on (1, 0), and det = 1 at each."}, {"q": "f(x) = x³. Is f one-to-one near 0?", "a": "yes, though f′(0) = 0", "w": ["no, since f′(0) = 0", "only for x > 0", "no, it repeats"], "why": "det 0 costs the undoing its slope, not its existence."}, {"q": "(x, y) ↦ (eˣ cos y, eˣ sin y). Is it one-to-one on the plane?", "a": "no: y and y + 2π give the same point", "w": ["yes: its det is never 0", "yes: eˣ is one-to-one", "no: its det is 0 at y = 0"], "why": "det e²ˣ ≠ 0 gives only local undoing."}, {"q": "Accepted name for the local-undo and undo-slope techniques together?", "a": "the inverse function theorem", "w": ["the implicit function theorem", "the chain rule", "the fixed point rule"], "why": "A local change of coordinates."}, {"q": "Polar map at r = 2, θ = π/6. What is det DT?", "a": "2", "w": ["1", "4", "√3"], "why": "det DT = r."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28f"]=[{"q": "F(a, b) = 0 and F<sub>y</sub>(a, b) ≠ 0. What follows?", "a": "near a, the equation fixes y as a smoothly sloped g(x)", "w": ["y is a function of x on the whole curve", "F<sub>x</sub>(a, b) = 0", "the curve has a top at (a, b)"], "why": "The fixed-by-an-equation technique."}, {"q": "G(x, y) = (x, F(x, y)). What is det DG?", "a": "F<sub>y</sub>", "w": ["F<sub>x</sub>", "F<sub>x</sub> F<sub>y</sub>", "1"], "why": "A stair grid: the product down the middle is 1 · F<sub>y</sub>."}, {"q": "Which technique turns G = (x, F) round to give g?", "a": "the local-undo technique", "w": ["the implicit-slope technique", "the swap-knobs technique", "the stretch-bound technique"], "why": "det DG = F<sub>y</sub> ≠ 0, so 28e applies."}, {"q": "Slope of y = g(x) on F(x, y) = 0?", "a": "−F<sub>x</sub>/F<sub>y</sub>", "w": ["−F<sub>y</sub>/F<sub>x</sub>", "F<sub>x</sub>/F<sub>y</sub>", "F<sub>x</sub> F<sub>y</sub>"], "why": "The implicit-slope technique: the roads add to 0."}, {"q": "x² + y² = 25 at (3, 4). What is the slope?", "a": "−3/4", "w": ["−4/3", "3/4", "4/3"], "why": "F<sub>x</sub> = 6, F<sub>y</sub> = 8."}, {"q": "x² + y² = 25 at (5, 0). Does the technique fix y as a function of x?", "a": "no: F<sub>y</sub> = 0 and the circle stands straight up", "w": ["yes: F(5, 0) = 0", "yes: F<sub>x</sub> ≠ 0", "no: (5, 0) is not on the circle"], "why": "Near x = 5 there are two y’s on one side and none on the other."}, {"q": "y³ = x at (0, 0), where F<sub>y</sub> = 0. Is there a function g?", "a": "yes, ∛x, but it has no slope at 0", "w": ["no, the technique forbids it", "yes, with slope 0", "no, the curve has a corner"], "why": "The technique’s silence is not a no."}, {"q": "x³ + y³ = 6xy at (3, 3). What is the slope?", "a": "−1", "w": ["1", "0", "−9"], "why": "F<sub>x</sub> = F<sub>y</sub> = 9."}, {"q": "Accepted name for the fixed-by-an-equation technique?", "a": "the implicit function theorem", "w": ["the inverse function theorem", "the chain rule", "the multiplier method"], "why": "g is defined implicitly by F(x, y) = 0."}, {"q": "Can one g of x describe the whole circle x² + y² = 25?", "a": "no: x = 3 has the points (3, 4) and (3, −4)", "w": ["yes: g(x) = √(25 − x²)", "yes: near every point", "no: the circle has no slopes"], "why": "The technique fixes g near one point only."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28g"]=[{"q": "∇f = (f<sub>x</sub>, f<sub>y</sub>). What is it called on the page?", "a": "the uphill vector", "w": ["the slope grid", "the level curve", "the best flat map"], "why": "Accepted name: the gradient."}, {"q": "∇f(w) ≠ 0. Along which direction is the slope of f greatest?", "a": "along ∇f(w)", "w": ["along a level curve", "along (1, 1)", "at right angles to ∇f(w)"], "why": "The uphill technique: ∇f · u ≤ |∇f|, with equality along ∇f."}, {"q": "f = x² + 3y at (2, −1). What is the steepest slope?", "a": "5", "w": ["7", "4", "25"], "why": "|∇f| = |(4, 3)| = 5."}, {"q": "What angle does ∇f make with a level curve of f?", "a": "a right angle", "w": ["zero: it runs along it", "45 degrees", "it depends on f"], "why": "Along a level curve f is constant, so ∇f · (x′, y′) = 0."}, {"q": "f has a top on g = 0 at w, ∇g(w) ≠ 0. What follows?", "a": "∇f(w) = λ∇g(w) for some λ", "w": ["∇f(w) = 0", "∇g(w) = 0", "f<sub>x</sub> + f<sub>y</sub> = 0"], "why": "The lines-up technique."}, {"q": "Which technique licenses 0 = h′(w₁) for h(x) = f(x, φ(x)) at a best point?", "a": "the flat-top technique", "w": ["the lines-up technique", "the uphill technique", "the stretch-bound technique"], "why": "14a: a top or bottom of a function of one input has slope 0."}, {"q": "Best rectangle area xy with perimeter 40. What do the lines-up equations give?", "a": "x = y = 10, a square", "w": ["x = 20, y = 0", "x = 5, y = 15", "x = y = 20"], "why": "(y, x) = λ(2, 2)."}, {"q": "∇f = λ∇g at a point of g = 0. Is it a top?", "a": "not always: check it", "w": ["yes, always", "no, always a bottom", "yes, if λ > 0"], "why": "The vectors also line up at bottoms and at flat-but-neither points."}, {"q": "f = x on y² = x³. Why do the lines-up equations miss the best point (0, 0)?", "a": "∇g = 0 at the cusp", "w": ["∇f = 0 there", "f has no top", "the curve is not closed"], "why": "With ∇g(w) = 0 the technique is silent."}, {"q": "Accepted name for λ in the lines-up technique?", "a": "a multiplier", "w": ["a gradient", "a Jacobian", "an eigenvalue"], "why": "It is how fast the best value changes as the constraint loosens."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28h"]=[{"q": "Σ m<sub>ij</sub>|R<sub>ij</sub>|, with m<sub>ij</sub> the inf of f on each box. What is it?", "a": "a lower column sum", "w": ["an upper column sum", "a corner sum", "a total of totals"], "why": "Columns from below."}, {"q": "f is continuous on the rectangle R. What follows?", "a": "f is integrable on R", "w": ["f is 0 on the edge of R", "the column sums are equal", "f has a best flat map on R"], "why": "The rectangle-total technique."}, {"q": "Which technique licenses M<sub>ij</sub> − m<sub>ij</sub> ≤ ε on boxes small enough?", "a": "the evenly-continuous technique", "w": ["the either-order technique", "the no-gaps axiom", "the average-slope technique"], "why": "15f, run on R with quarters."}, {"q": "∫₀¹ (∫₀² f dy) dx = ∫₀² (∫₀¹ f dx) dy for continuous f. What is this?", "a": "the either-order technique", "w": ["the rectangle-total technique", "the change-of-variables technique", "the swap-knobs technique"], "why": "Rows or columns, the same total."}, {"q": "∬ xy² over [0, 2] × [0, 1]. What is it?", "a": "2/3", "w": ["4/3", "1/3", "2"], "why": "∫₀² x · (1/3) dx = 2/3."}, {"q": "∬<sub>R</sub> 1 over [1, 4] × [2, 7]. What is it?", "a": "15", "w": ["3", "5", "21"], "why": "The total of 1 is the area of R."}, {"q": "Does ∬ fg = (∬ f)(∬ g) over [0, 1]²?", "a": "only when the product splits as f(x)g(y)", "w": ["always", "never", "only when f = g"], "why": "With f = g = x: 1/3 against 1/4."}, {"q": "f = x + y on [0, 2] × [0, 1]. What is the total?", "a": "3", "w": ["2", "1.5", "4.5"], "why": "Height 1.5 at the centre times area 2."}, {"q": "∫ₐᵇ (∫꜀ᵈ f dy) dx, a total of totals. Accepted name?", "a": "an iterated integral", "w": ["a line integral", "a flux integral", "a partial integral"], "why": "By the either-order technique it equals the double integral."}, {"q": "The limits of a total of totals. Which inner total runs from c to d?", "a": "the one along y", "w": ["the one along x", "the outer one", "either, by choice"], "why": "Each limit belongs to its own variable."}];
