(window.LADDER_CARDS=window.LADDER_CARDS||{})["28j"]=[{"q": "∫ (P x′ + Q y′) dt along a path. What is it?", "a": "the circulation of F along the path", "w": ["the flux across the path", "the swirl of F", "the spread of F"], "why": "It totals the part of F along the way."}, {"q": "∫ (P y′ − Q x′) dt along a path. What is it?", "a": "the flux of F across the path", "w": ["the circulation along the path", "the uphill-total", "the area inside"], "why": "It totals the part of F crossing to the right."}, {"q": "Q<sub>x</sub> − P<sub>y</sub>. What is it called on the page?", "a": "the swirl", "w": ["the spread", "the circulation", "the uphill vector"], "why": "Accepted name: the curl, in the plane."}, {"q": "P<sub>x</sub> + Q<sub>y</sub>. What is it called on the page?", "a": "the spread", "w": ["the swirl", "the flux", "the corner sum"], "why": "Accepted name: the divergence."}, {"q": "F = ∇φ. What is the circulation of F along a path?", "a": "φ at the end minus φ at the start", "w": ["0 along every path", "the total of the swirl", "|∇φ| times the length"], "why": "The uphill-total technique."}, {"q": "Circulation round the edge of R, travelled with R on the left. What does it equal?", "a": "∬<sub>R</sub> (Q<sub>x</sub> − P<sub>y</sub>)", "w": ["∬<sub>R</sub> (P<sub>x</sub> + Q<sub>y</sub>)", "0", "∬<sub>R</sub> (P<sub>y</sub> − Q<sub>x</sub>)"], "why": "The swirl technique."}, {"q": "Which technique turns flux into circulation, with G = (−Q, P)?", "a": "the swirl technique", "w": ["the uphill-total technique", "the chain-of-flat-maps technique", "the change-of-variables technique"], "why": "The swirl of G is the spread of F; this gives the spread technique."}, {"q": "F = (−y, x). What is its circulation round the unit circle?", "a": "2π", "w": ["0", "π", "4π"], "why": "So F is not uphill from anything."}, {"q": "F = (−y, x)/(x² + y²) has swirl 0 off the origin. What is its circulation round the unit circle?", "a": "2π, since F blows up inside", "w": ["0, by the swirl technique", "π", "−2π"], "why": "The swirl technique needs F smoothly sloped on all of R."}, {"q": "Accepted name for an uphill field?", "a": "a conservative field", "w": ["a swirling field", "a level field", "a spread field"], "why": "Also called a gradient field, with φ its potential."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28k"]=[{"q": "The tangent plane of z = f(x, y) at (w, b):", "a": "z = f(w, b) + fₓ(w, b)(x − w) + f_y(w, b)(y − b)", "w": ["z = fₓ(w, b)(x − w) + f_y(w, b)(y − b)", "z = f(w, b) + fₓ(w, b)(y − b) + f_y(w, b)(x − w)", "z = f(w, b) + (fₓ + f_y)(x − w)"], "why": "The one plane whose gap shrinks faster than the distance."}, {"q": "Why is the tangent plane the only plane whose gap shrinks faster than the distance?", "a": "The one-flat-map technique: a function has at most one best flat map", "w": ["The smooth-knobs technique alone", "The each-place technique", "Every plane through the point has the same tilt"], "why": "Two such planes would give two best flat maps (28b1)."}, {"q": "f = 1000 − 0.001x² − 0.002y². Its uphill vector at (200, 100):", "a": "(−0.4, −0.4)", "w": ["(0.4, 0.4)", "(−0.2, −0.4)", "(−40, −20)"], "why": "fₓ = −0.002x, f_y = −0.004y."}, {"q": "Slopes along two vectors of length 1 fix ∇f exactly when the two vectors:", "a": "are not along one line", "w": ["are at right angles", "both have positive places", "point the same way"], "why": "Free vectors give det ≠ 0, and the det-ratio technique solves."}, {"q": "A trail due east falls 0.10 per metre; due north climbs 0.20. The slope along (0.6, 0.8):", "a": "0.10", "w": ["0.30", "−0.10", "0.22"], "why": "∇f = (−0.10, 0.20); dot with (0.6, 0.8): −0.06 + 0.16."}, {"q": "The line touching x²/4 + y² = 2 at (2, 1):", "a": "x + 2y = 4", "w": ["2x + y = 5", "x + y = 3", "x − 2y = 0"], "why": "∇F(2, 1) = (1, 2); the level-plane technique."}, {"q": "The plane touching x² + y² + z² = 14 at (1, 2, 3):", "a": "x + 2y + 3z = 14", "w": ["x + 2y + 3z = 0", "2x + 4y + 6z = 14", "x + y + z = 6"], "why": "∇F = (2, 4, 6) at the point."}, {"q": "Writing z = f(x, y) as a level surface F = f − z = 0, ∇F is:", "a": "(fₓ, f_y, −1)", "w": ["(fₓ, f_y, 1)", "(fₓ, f_y, 0)", "(fₓ, f_y, f)"], "why": "The slope of −z along z is −1."}, {"q": "Which step licenses: near p, with F_z(p) ≠ 0, the level surface F = c is a graph z = g(x, y)?", "a": "The fixed-by-an-equation technique (28f1)", "w": ["The uphill technique (28g1)", "The tangent-plane technique (28k1)", "The swap-knobs technique (28d2)"], "why": "An equation fixes one unknown as a smoothly sloped function of the rest."}, {"q": "On a hill, the uphill vector points:", "a": "the steepest way up from where you stand", "w": ["straight at the top", "along the line of equal height", "to the lowest point"], "why": "28g1; on a lopsided hill the top lies elsewhere."}, {"q": "Lines of equal height every 100 m are 500 m apart on the ground. The steepest slope there is about:", "a": "1 in 5", "w": ["1 in 50", "5 in 1", "1 in 500"], "why": "Height grows at |∇f| per metre: 100/500."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28l"]=[{"q": "The second-slope grid of f at p (accepted name: the Hessian):", "a": "rows (fₓₓ, fₓᵧ), (fₓᵧ, fᵧᵧ)", "w": ["rows (fₓ, f_y), (f_y, fₓ)", "rows (fₓₓ, 0), (0, fᵧᵧ)", "rows (fₓₓ, fᵧᵧ), (fᵧᵧ, fₓₓ)"], "why": "The same flipped across its middle, by the swap-knobs technique."}, {"q": "The hug of degree 2 of f at p:", "a": "f(p) + ∇f(p) · h + ½ hᵀH(p)h", "w": ["f(p) + ∇f(p) · h + hᵀH(p)h", "f(p) + ½∇f(p) · h + hᵀH(p)h", "f(p) + ∇f(p) · h"], "why": "The surface-match technique."}, {"q": "The hug of eˣ cos y at (0, 0):", "a": "1 + x + ½(x² − y²)", "w": ["1 + x + ½(x² + y²)", "1 + x − y²", "1 + y + ½(x² − y²)"], "why": "fₓₓ = 1, fₓᵧ = 0, fᵧᵧ = −1."}, {"q": "Which step licenses g″(t) = hᵀH(p + th)h for g(t) = f(p + th)?", "a": "The roads-add technique, used twice (28c3)", "w": ["The one-knob technique (28a2)", "The each-place technique (28a1)", "The tangent-plane technique (28k1)"], "why": "Each slope of g is a sum over the roads."}, {"q": "At a flat point, A = 2, B = 1, C = 3. The grid test says:", "a": "a bottom", "w": ["a top", "a saddle", "it cannot tell"], "why": "D = 6 − 1 = 5 > 0, A > 0."}, {"q": "At a flat point, A = 2, B = 3, C = 2. The grid test says:", "a": "a saddle", "w": ["a bottom", "a top", "it cannot tell"], "why": "D = 4 − 9 = −5 < 0."}, {"q": "x⁴ + y⁴ at (0, 0): D and the truth:", "a": "D = 0, and a bottom", "w": ["D = 0, and a saddle", "D > 0, and a bottom", "D < 0, and a saddle"], "why": "D = 0 means the test is silent, not that there is no bottom."}, {"q": "(y − x²)(y − 3x²) at (0, 0):", "a": "a bottom along every line, yet no bottom", "w": ["a bottom", "a top along every line", "a saddle with D < 0"], "why": "Along y = 2x² it is −x⁴."}, {"q": "If every third partial slope has size at most K, the hug's error is at most:", "a": "K(|h₁| + |h₂|)³/6", "w": ["K(|h₁| + |h₂|)²/2", "K|h|³", "K(|h₁| + |h₂|)³/2"], "why": "The hug-ceiling technique: 23b's ceiling along one line."}, {"q": "The flat points of x³ + y³ − 3xy:", "a": "(0, 0), a saddle, and (1, 1), a bottom", "w": ["(0, 0), a bottom, and (1, 1), a saddle", "(1, 1) only, a bottom", "(0, 0) and (−1, −1), both saddles"], "why": "H = rows (6x, −3), (−3, 6y)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28m"]=[{"q": "0 ≤ x ≤ 1, x ≤ y ≤ 1, described with y outside:", "a": "0 ≤ y ≤ 1, 0 ≤ x ≤ y", "w": ["0 ≤ y ≤ 1, y ≤ x ≤ 1", "0 ≤ y ≤ x, 0 ≤ x ≤ 1", "x ≤ y ≤ 1, 0 ≤ x ≤ 1"], "why": "The same triangle, read across."}, {"q": "∫₀¹∫ₓ¹ e^(y²) dy dx equals:", "a": "(e − 1)/2", "w": ["e − 1", "(e − 1)/4", "e/2"], "why": "Swap: ∫₀¹ y e^(y²) dy."}, {"q": "Which step licenses swapping the order on a region slanted both ways?", "a": "The order-swap technique (28m1), from 28i3's slanted totals", "w": ["The either-order technique on a rectangle alone", "The area-scale technique (28i1)", "The substitution technique for areas alone"], "why": "Both totals in strips equal ∬_D f."}, {"q": "The extra factor in round measures:", "a": "r", "w": ["r²", "1/r", "θ"], "why": "|det| of the slope grid of (r cos θ, r sin θ)."}, {"q": "The volume under z = 4 − x² − y² over x² + y² ≤ 4:", "a": "8π", "w": ["16π", "4π", "32π/3"], "why": "∫₀^2π∫₀² (4 − r²) r dr dθ."}, {"q": "The area inside r = 1 + cos θ:", "a": "3π/2", "w": ["2π", "π", "3π"], "why": "∫ ½(1 + cos θ)² dθ."}, {"q": "The volume scale in ball measures, φ measured down from the top:", "a": "ρ² sin φ", "w": ["ρ² cos φ", "ρ sin φ", "ρ²"], "why": "The expansion technique along the bottom row."}, {"q": "The volume scale in cylinder measures:", "a": "r", "w": ["r²", "1", "rz"], "why": "The round-measure grid with a 1 for z."}, {"q": "∫₀^2π∫₀^π∫₀^a ρ² sin φ dρ dφ dθ:", "a": "4πa³/3", "w": ["4πa²", "2πa³/3", "πa³"], "why": "The ball, as 21o found by slices."}, {"q": "The disc (x − 1)² + y² ≤ 1 in round measures:", "a": "0 ≤ r ≤ 2 cos θ, −π/2 ≤ θ ≤ π/2", "w": ["0 ≤ r ≤ 1, 0 ≤ θ ≤ 2π", "0 ≤ r ≤ cos θ, 0 ≤ θ ≤ π", "1 ≤ r ≤ 2, 0 ≤ θ ≤ 2π"], "why": "r² = 2r cos θ on the edge."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28n"]=[{"q": "The work of F along r(t), α ≤ t ≤ β:", "a": "∫ F(r(t)) · r′(t) dt", "w": ["∫ F(r(t)) · r′(t)/|r′(t)| dt", "∫ |F(r(t))| |r′(t)| dt", "∫ F(r(t)) dt"], "why": "The circulation of 28j1, in any number of places."}, {"q": "Tracing a curve backwards does what to ∫_C f ds?", "a": "Nothing", "w": ["Turns its sign", "Doubles it", "Makes it 0"], "why": "|r′| is never negative: the retrace technique."}, {"q": "Tracing a curve backwards does what to the work?", "a": "Turns its sign", "w": ["Nothing", "Doubles it", "Makes it 0"], "why": "The ends of the total swap."}, {"q": "Which step licenses: work along every path from A to B is φ(B) − φ(A)?", "a": "The uphill-total technique (28j1)", "w": ["The cross-slopes technique (28n2)", "The swirl technique (28j2)", "The retrace technique (28n1)"], "why": "Roads add, then the area-is-a-change technique."}, {"q": "On a rectangle, (P, Q) is uphill from something exactly when:", "a": "P_y = Qₓ", "w": ["Pₓ = Q_y", "Pₓ + Q_y = 0", "P = Q"], "why": "The cross-slopes technique."}, {"q": "A potential of (2xy + 3, x² + 4y):", "a": "x²y + 3x + 2y²", "w": ["x²y + 3x", "x²y + 4y² + 3x", "2xy² + 3y"], "why": "∫P dx, then match Q with c(y) = 2y²."}, {"q": "(−y, x)/(x² + y²) on the plane with 0 taken out:", "a": "cross slopes agree, yet it is uphill from nothing there", "w": ["uphill from θ on the whole punctured plane", "its cross slopes differ", "its circulation round 0 is 0"], "why": "It works 2π round the circle about 0."}, {"q": "The area of a patch r(u, v) over S:", "a": "∬_S |r_u × r_v|", "w": ["∬_S |r_u| |r_v|", "∬_S r_u · r_v", "∬_S |r_u + r_v|"], "why": "Each small piece is a parallelogram (27i3)."}, {"q": "Retracing a patch by T with det DT < 0 does what to the flux?", "a": "Turns its sign", "w": ["Nothing", "Multiplies it by det DT", "Makes it 0"], "why": "q_s × q_t = det DT (r_u × r_v)."}, {"q": "The flux of (x, y, z) out of the sphere of radius a:", "a": "4πa³", "w": ["4πa²", "4πa³/3", "0"], "why": "F is a times the outward vector; the area is 4πa²."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28o"]=[{"q": "A downhill step of size η from p goes to:", "a": "p − η∇f(p)", "w": ["p + η∇f(p)", "p − ∇f(p)/η", "p − η|∇f(p)|"], "why": "Against the uphill vector."}, {"q": "The slope of g(η) = f(p − η∇f(p)) at η = 0:", "a": "−|∇f(p)|²", "w": ["|∇f(p)|²", "−|∇f(p)|", "0"], "why": "The roads-add technique."}, {"q": "On ½(x² + 10y²), the walk heads to the bottom exactly when:", "a": "0 < η < 0.2", "w": ["0 < η < 2", "0 < η < 0.1", "0 < η < 1"], "why": "η < 2/λₙ with λₙ = 10."}, {"q": "The best fixed step on ½(λ₁x² + λₙy²):", "a": "2/(λ₁ + λₙ)", "w": ["1/λₙ", "2/λₙ", "1/(λ₁ + λₙ)"], "why": "Balances |1 − ηλ₁| against |1 − ηλₙ|."}, {"q": "With that best step, the factor per step:", "a": "(λₙ − λ₁)/(λₙ + λ₁)", "w": ["λ₁/λₙ", "1 − λ₁/λₙ", "(λₙ + λ₁)/(λₙ − λ₁)"], "why": "Narrow valleys, factor near 1, are slow."}, {"q": "Each downhill step on a bowl is the forward step of 24i on:", "a": "x′ = −∇f(x)", "w": ["x′ = ∇f(x)", "x′ = −x", "x″ = −∇f(x)"], "why": "The stiff-step condition ηλᵢ < 2 returns."}, {"q": "x² + 4y² from (2, 1) with η = 0.3: f goes from 8 to:", "a": "8.48", "w": ["2.72", "0", "5"], "why": "The y place is multiplied by −1.4."}, {"q": "fₓₓ > 0 and D > 0 everywhere give:", "a": "f bends up along every line, and any flat point is the one bottom", "w": ["f has no bottom", "every flat point is a saddle", "the walk runs away for every η"], "why": "The one-bottom technique."}, {"q": "x² + xy + y² − 3x has its one bottom at:", "a": "(2, −1)", "w": ["(1, 1)", "(3, 0)", "(−1, 2)"], "why": "2x + y = 3, x + 2y = 0."}, {"q": "A walk with a fixed step that settles can only settle at:", "a": "a flat point", "w": ["the lowest point of f", "a saddle", "the start"], "why": "Steps η∇f(xₖ) head to 0."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28p"]=[{"q": "If |∂f/∂xᵢ| ≤ Mᵢ on the box and |hᵢ| ≤ Δᵢ, then |f(p + h) − f(p)| is at most:", "a": "M₁Δ₁ + ⋯ + MₙΔₙ", "w": ["max Mᵢ · max Δᵢ", "(M₁ + ⋯ + Mₙ)/n", "√(M₁²Δ₁² + ⋯)"], "why": "The error-bound technique."}, {"q": "Which step licenses f(p + h) − f(p) = g′(c) in that proof?", "a": "The average-slope technique (14c)", "w": ["The roads-add technique (28c3)", "The one-knob technique (28a2)", "The tangent-plane technique (28k1)"], "why": "g(t) = f(p + th) on [0, 1]."}, {"q": "V = πr²h, r = 3.30 ± 0.02 cm, h = 12.2 ± 0.1 cm. Flat estimate of the doubt:", "a": "about 8.5 cm³", "w": ["0.12 cm³", "about 85 cm³", "about 2 cm³"], "why": "253 · 0.02 + 34.2 · 0.1."}, {"q": "For f = c x^a y^b, to first order the share of doubt in f is at most:", "a": "|a| e_x + |b| e_y", "w": ["e_x + e_y", "|a e_x · b e_y|", "max(|a| e_x, |b| e_y)"], "why": "The relative-errors-add technique."}, {"q": "g = 4π²L/T² with 0.2% in L and 0.25% in T: the share in g is about:", "a": "0.7%", "w": ["0.45%", "0.05%", "1.4%"], "why": "0.2 + 2 · 0.25."}, {"q": "10.0 ± 0.1 minus 9.8 ± 0.1:", "a": "0.2 ± 0.2", "w": ["0.2 ± 0.002", "0.2 ± 0.0", "0.2 ± 0.02"], "why": "For a difference the doubts add, not the shares."}, {"q": "The share of doubt in √x, if x has 1%:", "a": "0.5%", "w": ["2%", "1%", "0.1%"], "why": "Through a power the share is multiplied by the power."}, {"q": "When x is found by undoing y = F(x), the doubt in x is about:", "a": "J⁻¹ times the doubt in y", "w": ["J times the doubt in y", "det J times the doubt in y", "the doubt in y"], "why": "The undo-error technique."}, {"q": "Two beacons at (0, 0) and (10, 0): det J of the distance map at (x, y):", "a": "10y/(d₁d₂)", "w": ["10x/(d₁d₂)", "d₁d₂", "y/10"], "why": "Small near the line through the beacons."}, {"q": "x₁ + x₂ = 2, x₁ + 1.01x₂ = 2.01, right sides ± 0.005: worst doubt in x₁ about:", "a": "1", "w": ["0.005", "0.01", "100"], "why": "The undone grid has entries about 100."}, {"q": "Doubts that fall at random partly cancel. How much they cancel is:", "a": "a question about chance, for later", "w": ["always half", "never: they always add", "zero for products"], "why": "The ceilings here take every doubt the bad way."}];
